mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM effective_attendance_event event
    JOIN employee roster_employee
      ON roster_employee.employee_id = event.employee_id
     AND roster_employee.company_id = #{companyId}
    WHERE event.created_at <= #{dataAsOf}
      AND (
            (
                event.event_kind = 'PUNCH_POINT'
                AND event.point_instant >= TIMESTAMPADD(HOUR, -8, CAST(#{periodStart} AS DATETIME))
                AND event.point_instant < TIMESTAMPADD(HOUR, -8, CAST(#{periodEndExclusive} AS DATETIME))
            )
            OR (
                event.event_kind = 'OA_INTERVAL'
                AND event.interval_end > TIMESTAMPADD(HOUR, -8, CAST(#{periodStart} AS DATETIME))
                AND event.interval_start < TIMESTAMPADD(HOUR, -8, CAST(#{periodEndExclusive} AS DATETIME))
            )
          )
) THEN 1 ELSE 0 END AS hasEvidence

SELECT #{organizationId}
UNION
SELECT closure.descendant_organization_id
FROM organization_current_closure closure
WHERE closure.ancestor_organization_id = #{organizationId}

SELECT employee.employee_id AS employeeId,
       employee_version.employee_number AS employeeNumber,
       employee_version.display_name AS employeeName,
       employment.organization_id AS organizationId,
       organization_version.name AS organizationName
FROM employee employee
JOIN employee_version employee_version
  ON employee_version.employee_id = employee.employee_id
 AND employee_version.status = 'ACTIVE'
 AND employee_version.effective_from <= #{asOf}
 AND (
        employee_version.effective_to IS NULL
        OR employee_version.effective_to > #{asOf}
 )
JOIN employment_assignment employment
  ON employment.employee_id = employee.employee_id
 AND employment.version_valid_to IS NULL
 AND employment.record_status = 'ACTIVE'
 AND employment.effective_from <= #{asOf}
 AND (
        employment.effective_to IS NULL
        OR employment.effective_to > #{asOf}
 )
JOIN organization_version organization_version
  ON organization_version.organization_id = employment.organization_id
 AND organization_version.status = 'ACTIVE'
 AND organization_version.effective_from <= #{asOf}
 AND (
        organization_version.effective_to IS NULL
        OR organization_version.effective_to > #{asOf}
 )
WHERE employee.company_id = #{companyId}

      AND employee.employee_id IN

          #{id}



      AND employment.organization_id IN

          #{id}


ORDER BY employee_version.employee_number
LIMIT 2000

SELECT /*!80000 STRAIGHT_JOIN */ COUNT(*)
FROM attendance_report_exception_fact fact
JOIN employee_version employee_version
  ON employee_version.employee_version_id = fact.employee_version_id
WHERE 
  AND fact.business_date >= #{fromDate}
  AND fact.business_date < #{toDateExclusive}



      AND fact.severity = #{severity}


      AND fact.state = #{state}

SELECT /*!80000 STRAIGHT_JOIN */ fact.exception_case_id AS caseId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.business_date AS businessDate, fact.exception_type AS exceptionType, fact.severity, fact.state, fact.exception_minutes AS exceptionMinutes, fact.safe_evidence_summary AS details, daily.first_punch_at AS firstPunchAt, daily.last_punch_at AS lastPunchAt FROM attendance_report_exception_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id LEFT JOIN ( SELECT daily_fact.attendance_report_projection_id, daily_fact.employee_id, daily_fact.business_date, MIN(daily_fact.first_punch_at) AS first_punch_at, MAX(daily_fact.last_punch_at) AS last_punch_at FROM attendance_report_daily_fact daily_fact WHERE daily_fact.attendance_report_projection_id IN
#{id}
GROUP BY daily_fact.attendance_report_projection_id, daily_fact.employee_id, daily_fact.business_date ) daily ON daily.attendance_report_projection_id = fact.attendance_report_projection_id AND daily.employee_id = fact.employee_id AND daily.business_date = fact.business_date WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
AND fact.severity = #{severity}
AND fact.state = #{state}
ORDER BY fact.business_date, employee_version.employee_number, fact.exception_case_id LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT fact.attendance_report_oa_fact_id FROM attendance_report_oa_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id
WHERE AND (CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END) IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
AND (CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END) = #{sourceStatus}
AND DAY(TIMESTAMPADD(HOUR, 8, COALESCE(fact.interval_start, fact.point_instant))) = #{occurrenceDay}
UNION ALL SELECT fact.attendance_report_hr_paper_fact_id FROM attendance_report_hr_paper_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE fact.attendance_report_projection_id IN
#{id}
AND fact.company_id = #{companyId} AND fact.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
AND fact.source_status = #{sourceStatus}
AND DAY(TIMESTAMPADD(HOUR, 8, COALESCE(fact.interval_start, fact.point_instant))) = #{occurrenceDay}
) AS combined_facts

SELECT documentId, employeeId, employeeNumber, employeeName, organizationId, organizationName, documentType, leaveType, startAt, endExclusive, recognizedMinutes, sourceStatus, sourceOrigin, projectionStart, projectionEndExclusive, recognizedMinutesByDateJson, projectionDataAsOf FROM ( SELECT fact.oa_attendance_document_id AS documentId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.document_type AS documentType, COALESCE( NULLIF(fact.leave_type_code, ''), context.overtime_type, CASE WHEN fact.document_type = 'TIME_OFF' THEN 'TIME_OFF' END) AS leaveType, COALESCE(fact.interval_start, fact.point_instant) AS startAt, COALESCE(fact.interval_end, TIMESTAMPADD(MICROSECOND, 1, fact.point_instant)) AS endExclusive, fact.recognized_minutes AS recognizedMinutes, CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END AS sourceStatus, CASE WHEN document.source_business_key LIKE 'PAPER:%' THEN 'PAPER' ELSE 'OA' END AS sourceOrigin, projection.period_start AS projectionStart, projection.period_end_exclusive AS projectionEndExclusive, fact.recognized_minutes_by_date_json AS recognizedMinutesByDateJson, projection.data_as_of AS projectionDataAsOf FROM attendance_report_oa_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id LEFT JOIN oa_attendance_document document ON document.oa_attendance_document_id = fact.oa_attendance_document_id JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id
WHERE AND (CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END) IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
AND (CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END) = #{sourceStatus}
AND DAY(TIMESTAMPADD(HOUR, 8, COALESCE(fact.interval_start, fact.point_instant))) = #{occurrenceDay}
UNION ALL SELECT fact.source_document_key AS documentId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.document_type AS documentType, COALESCE( NULLIF(fact.leave_type_code, ''), CASE WHEN fact.document_type = 'TIME_OFF' THEN 'TIME_OFF' END) AS leaveType, COALESCE(fact.interval_start, fact.point_instant) AS startAt, COALESCE(fact.interval_end, TIMESTAMPADD(MICROSECOND, 1, fact.point_instant)) AS endExclusive, fact.recognized_minutes AS recognizedMinutes, fact.source_status AS sourceStatus, 'PAPER' AS sourceOrigin, projection.period_start AS projectionStart, projection.period_end_exclusive AS projectionEndExclusive, fact.recognized_minutes_by_date_json AS recognizedMinutesByDateJson, projection.data_as_of AS projectionDataAsOf FROM attendance_report_hr_paper_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE fact.attendance_report_projection_id IN
#{id}
AND fact.company_id = #{companyId} AND fact.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
AND fact.source_status = #{sourceStatus}
AND DAY(TIMESTAMPADD(HOUR, 8, COALESCE(fact.interval_start, fact.point_instant))) = #{occurrenceDay}
) AS combined ORDER BY startAt, employeeNumber LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT fact.employee_id FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
GROUP BY fact.employee_id HAVING 1 = 1
AND SUM(fact.late_minutes) > 0
) aggregated

SELECT fact.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName, SUM(CASE WHEN fact.late_minutes > 0 THEN 1 ELSE 0 END) AS lateEvents, SUM(fact.late_minutes) AS lateMinutes, SUM(fact.penalized_late_minutes) AS penalizedLateMinutes, SUM(fact.missing_punch_count) AS missingPunches, SUM(fact.scheduled_minutes) AS scheduledMinutes, SUM(fact.paid_overtime_minutes) AS paidOvertimeMinutes, SUM(fact.compensatory_overtime_minutes) AS compensatoryOvertimeMinutes, SUM(fact.voluntary_overtime_minutes) AS voluntaryOvertimeMinutes, SUM(fact.leave_or_time_off_minutes) AS leaveMinutes, SUM(CASE WHEN fact.leave_type IN ('ANNUAL', 'ANNUAL_LEAVE') THEN fact.leave_or_time_off_minutes ELSE 0 END) AS annualLeaveMinutes, SUM(CASE WHEN fact.leave_type IN ( 'TIME_OFF', 'COMPENSATORY') THEN fact.leave_or_time_off_minutes ELSE 0 END) AS timeOffMinutes, SUM(fact.actual_work_minutes) AS actualWorkMinutes, SUM(fact.scheduled_attendance_days) AS scheduledAttendanceDays, SUM(fact.actual_attendance_days) AS actualAttendanceDays, CAST(NULL AS CHAR) AS employmentNote FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
GROUP BY fact.employee_id HAVING 1 = 1
AND SUM(fact.late_minutes) > 0
ORDER BY MAX(employee_version.employee_number) LIMIT #{limit} OFFSET #{offset}

SELECT fact.employee_id AS employeeId, fact.business_date AS businessDate, fact.day_type AS dayType, fact.leave_type AS leaveType, fact.late_minutes AS lateMinutes, fact.early_departure_minutes AS earlyDepartureMinutes, fact.missing_punch_count AS missingPunchCount, fact.first_punch_at AS firstPunchAt, fact.last_punch_at AS lastPunchAt, fact.paid_overtime_minutes AS paidOvertimeMinutes, fact.compensatory_overtime_minutes AS compensatoryOvertimeMinutes FROM attendance_report_daily_fact fact WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} AND fact.employee_id IN
#{id}
ORDER BY fact.employee_id, fact.business_date

SELECT fact.oa_attendance_document_id AS documentId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.document_type AS documentType, COALESCE( NULLIF(fact.leave_type_code, ''), context.overtime_type, CASE WHEN fact.document_type = 'TIME_OFF' THEN 'TIME_OFF' END) AS leaveType, COALESCE(fact.interval_start, fact.point_instant) AS startAt, COALESCE(fact.interval_end, TIMESTAMPADD(MICROSECOND, 1, fact.point_instant)) AS endExclusive, fact.recognized_minutes AS recognizedMinutes, CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END AS sourceStatus, CASE WHEN document.source_business_key LIKE 'PAPER:%' THEN 'PAPER' ELSE 'OA' END AS sourceOrigin, projection.period_start AS projectionStart, projection.period_end_exclusive AS projectionEndExclusive, fact.recognized_minutes_by_date_json AS recognizedMinutesByDateJson, projection.data_as_of AS projectionDataAsOf FROM attendance_report_oa_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id LEFT JOIN oa_attendance_document document ON document.oa_attendance_document_id = fact.oa_attendance_document_id LEFT JOIN oa_attendance_document_context context ON context.oa_attendance_document_id = fact.oa_attendance_document_id WHERE AND (CASE WHEN fact.source_status = 'UNKNOWN' AND fact.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE fact.source_status END) IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND fact.employee_id IN
#{id}
UNION ALL SELECT fact.source_document_key AS documentId, fact.employee_id AS employeeId, employee_version.employee_number AS employeeNumber, employee_version.display_name AS employeeName, fact.organization_id AS organizationId, organization_version.name AS organizationName, fact.document_type AS documentType, COALESCE( NULLIF(fact.leave_type_code, ''), CASE WHEN fact.document_type = 'TIME_OFF' THEN 'TIME_OFF' END) AS leaveType, COALESCE(fact.interval_start, fact.point_instant) AS startAt, COALESCE(fact.interval_end, TIMESTAMPADD(MICROSECOND, 1, fact.point_instant)) AS endExclusive, fact.recognized_minutes AS recognizedMinutes, fact.source_status AS sourceStatus, 'PAPER' AS sourceOrigin, projection.period_start AS projectionStart, projection.period_end_exclusive AS projectionEndExclusive, fact.recognized_minutes_by_date_json AS recognizedMinutesByDateJson, projection.data_as_of AS projectionDataAsOf FROM attendance_report_hr_paper_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE fact.attendance_report_projection_id IN
#{id}
AND fact.company_id = #{companyId} AND fact.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING')
AND fact.employee_id IN
#{id}

SELECT fact.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName, AS leaveType, SUM(fact.recognized_minutes) AS recognizedMinutes, COUNT(*) AS documentCount FROM attendance_report_oa_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE AND fact.document_type IN ('LEAVE', 'TIME_OFF')
AND ( fact.leave_type_code = #{leaveType} OR (#{leaveType} = 'COMPENSATORY' AND fact.document_type = 'TIME_OFF') )
GROUP BY fact.employee_id, leaveType ORDER BY MAX(employee_version.employee_number), leaveType LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id
WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
AND exemption.employee_id IS NULL

SELECT /*!80000 STRAIGHT_JOIN */ FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id
WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive}
AND exemption.employee_id IS NULL ORDER BY employee_version.employee_number, fact.business_date LIMIT #{limit} OFFSET #{offset}


  AND fact.recognized_overtime_minutes > 0

ORDER BY employee_version.employee_number, fact.business_date
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT fact.employee_id FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE GROUP BY fact.employee_id
HAVING SUM(fact.recognized_overtime_minutes) >= #{rateBelow} * 60
) people

SELECT fact.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE GROUP BY fact.employee_id
HAVING SUM(fact.recognized_overtime_minutes) >= #{rateBelow} * 60
ORDER BY MAX(employee_version.employee_number) LIMIT #{limit} OFFSET #{offset}

SELECT fact.employee_id AS employeeId, fact.business_date AS businessDate, fact.day_type AS dayType, fact.recognized_overtime_minutes AS recognizedOvertimeMinutes, fact.paid_overtime_minutes AS paidOvertimeMinutes, fact.compensatory_overtime_minutes AS compensatoryOvertimeMinutes, fact.voluntary_overtime_minutes AS voluntaryOvertimeMinutes FROM attendance_report_daily_fact fact JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} AND fact.recognized_overtime_minutes > 0
AND DAY(fact.business_date) = #{occurrenceDay}
ORDER BY fact.employee_id, fact.business_date

SELECT fact.employee_id AS employeeId, fact.business_date AS businessDate, fact.day_type AS dayType, fact.absence_minutes AS minutes FROM attendance_report_daily_fact fact WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} AND fact.absence_minutes > 0 AND fact.employee_id IN
#{id}
ORDER BY fact.employee_id, fact.business_date

SELECT fact.employee_id AS employeeId, fact.business_date AS businessDate, fact.leave_type AS dayType, fact.leave_or_time_off_minutes AS minutes FROM attendance_report_daily_fact fact WHERE AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} AND fact.leave_or_time_off_minutes > 0 AND fact.employee_id IN
#{id}
ORDER BY fact.employee_id, fact.business_date

SELECT COUNT(*)
FROM (

) missed_employees

SELECT universe.employee_id AS employeeId, MAX(employee_version.employee_number) AS employeeNumber, MAX(employee_version.display_name) AS employeeName, MAX(fact.organization_id) AS organizationId, MAX(organization_version.name) AS organizationName FROM (
) universe JOIN attendance_report_daily_fact fact ON fact.employee_id = universe.employee_id AND AND fact.business_date >= #{fromDate} AND fact.business_date < #{toDateExclusive} JOIN employee_version employee_version ON employee_version.employee_version_id = fact.employee_version_id JOIN organization_version organization_version ON organization_version.organization_version_id = fact.organization_version_id WHERE 1 = 1
GROUP BY universe.employee_id ORDER BY MAX(employee_version.employee_number), universe.employee_id LIMIT #{limit} OFFSET #{offset}

SELECT documents.document_id AS documentId, documents.employee_id AS employeeId, documents.period_start AS projectionStart, documents.period_end_exclusive AS projectionEndExclusive, documents.start_at AS startAt, documents.end_exclusive AS endExclusive, documents.recognized_minutes AS recognizedMinutes, documents.kind AS kind, documents.recognized_minutes_by_date_json AS recognizedMinutesByDateJson FROM ( SELECT COALESCE(fact.oa_attendance_document_id, fact.attendance_report_oa_fact_id) AS document_id, fact.employee_id, projection.period_start, projection.period_end_exclusive, COALESCE(fact.interval_start, fact.point_instant) AS start_at, COALESCE(fact.interval_end, fact.point_instant) AS end_exclusive, fact.recognized_minutes, fact.recognized_minutes_by_date_json, CASE WHEN fact.document_type = 'LEAVE' AND (CAST(fact.leave_type_code AS CHAR(64)) IN ('ANNUAL', 'ANNUAL_LEAVE') OR CAST(fact.leave_type_code AS CHAR(64)) LIKE '%年假%') THEN 'ANNUAL' WHEN fact.document_type = 'TIME_OFF' OR (fact.document_type = 'LEAVE' AND UPPER(COALESCE(CAST(fact.leave_type_code AS CHAR(64)), '')) IN ('COMPENSATORY', 'TIME_OFF', '调休', '调休假')) THEN 'TIME_OFF' WHEN fact.document_type = 'OVERTIME' AND (CAST(fact.leave_type_code AS CHAR(64)) LIKE '%COMPENSATORY%' OR CAST(fact.leave_type_code AS CHAR(64)) LIKE '%TIME_OFF%' OR CAST(fact.leave_type_code AS CHAR(64)) LIKE '%调休%') THEN 'COMPENSATORY_OT' ELSE NULL END AS kind FROM attendance_report_oa_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id AND projection.company_id = fact.company_id WHERE AND fact.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED') AND COALESCE(fact.interval_start, fact.point_instant) IS NOT NULL AND CAST(COALESCE(fact.interval_start, fact.point_instant) AS CHAR) >= '1970-01-01'
AND 1 = 0
AND fact.employee_id IN #{id}
) documents WHERE documents.kind IS NOT NULL
AND documents.kind IN ('TIME_OFF', 'COMPENSATORY_OT') AND documents.kind = 'ANNUAL'
ORDER BY documents.employee_id, documents.document_id, documents.period_start

SELECT COALESCE(fact.oa_attendance_document_id, fact.attendance_report_oa_fact_id) AS documentId, fact.employee_id AS employeeId, projection.period_start AS projectionStart, daily.business_date AS businessDate, daily.leave_or_time_off_minutes AS leaveMinutes, daily.leave_type AS leaveType, (SELECT COUNT(*) FROM attendance_report_oa_fact competing WHERE competing.attendance_report_projection_id = fact.attendance_report_projection_id AND competing.company_id = fact.company_id AND competing.employee_id = fact.employee_id AND competing.document_type IN ('LEAVE', 'TIME_OFF') AND (competing.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING') OR (competing.source_status = 'UNKNOWN' AND competing.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$')) AND competing.interval_start < TIMESTAMPADD(DAY, 1, TIMESTAMPADD(HOUR, -8, CAST(daily.business_date AS DATETIME))) AND competing.interval_end > TIMESTAMPADD(HOUR, -8, CAST(daily.business_date AS DATETIME))) AS effectiveDocumentCount FROM attendance_report_oa_fact fact JOIN attendance_report_projection projection ON projection.attendance_report_projection_id = fact.attendance_report_projection_id AND projection.company_id = fact.company_id JOIN attendance_report_daily_fact daily ON daily.attendance_report_projection_id = fact.attendance_report_projection_id AND daily.company_id = fact.company_id AND daily.employee_id = fact.employee_id AND daily.business_date >= projection.period_start AND daily.business_date < projection.period_end_exclusive AND fact.interval_start < TIMESTAMPADD(DAY, 1, TIMESTAMPADD(HOUR, -8, CAST(daily.business_date AS DATETIME))) AND fact.interval_end > TIMESTAMPADD(HOUR, -8, CAST(daily.business_date AS DATETIME)) WHERE fact.company_id = #{query.companyId} AND fact.document_type IN ('LEAVE', 'TIME_OFF') AND fact.source_status IN ('APPROVED', 'MODIFIED', 'SUPPLEMENTED') AND fact.recognized_minutes > 0 AND fact.recognized_minutes_by_date_json IS NULL
AND fact.attendance_report_projection_id IN #{id}
AND 1 = 0
AND fact.employee_id IN #{id}
AND 1 = 0
AND COALESCE(fact.oa_attendance_document_id, fact.attendance_report_oa_fact_id) IN #{id}
AND 1 = 0
ORDER BY fact.employee_id, documentId, projection.period_start, daily.business_date
